  "stuSess.refundContactNote": "Para solicitar um reembolso, entre em contato com <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Dúvidas ou problemas? Entre em contato com <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Seu reembolso foi iniciado pela Stripe.</p><p class=\"text-emerald-800 mt-1\">Reembolsos no cartão costumam ser recebidos em cerca de <strong>5–10 dias úteis</strong> (o prazo pode variar conforme o banco). Se não receber o valor no prazo habitual, envie um e-mail para <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Esta aula não parece ter sido paga pela Stripe da Tutlio (por exemplo, por transferência bancária ou em dinheiro). Não há reembolso automático neste caso.</p><p class=\"mt-2\">Para combinar o reembolso, entre em contato com seu professor <strong>{tutor}</strong> — use o e-mail ou os dados das suas reservas ou fornecidos pelo professor.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Esta aula não parece ter sido paga pela Stripe da Tutlio (por exemplo, por transferência bancária ou em dinheiro). Não há reembolso automático neste caso.</p><p class=\"mt-2\">Como suas aulas são oferecidas por uma organização, entre em contato com o <strong>administrador da organização</strong> (por meio do seu professor ou dos contatos publicados pela organização).</p>",
