  "enterpriseCheckout.continueToPayment": "Continuar para o pagamento",
  "pwa.bannerText": "Adicione a Tutlio à tela inicial para usá-la como um aplicativo!",
  "pwa.promptTitle": "Use a Tutlio como aplicativo",
  "pwa.promptSubtitle": "Adicionar à tela inicial",
  "pwa.promptDescription": "Instale a Tutlio no celular para uma experiência mais rápida, como a de um aplicativo — sem precisar de uma loja de aplicativos!",
  "pwa.howToInstall": "Como instalar?",
  "pwa.later": "Depois",
  "pwa.dontShowAgain": "Não mostrar novamente",
  "pwa.guideTitle": "Instalar como aplicativo no celular",
  "pwa.guideSubtitle": "Use a Tutlio como um aplicativo nativo no celular",
  "pwa.guideIntro": "Você pode adicionar a Tutlio à tela inicial do celular e usá-la como um aplicativo comum — em tela cheia e com acesso rápido.",
  "pwa.iosStep1": "Abra a Tutlio no Safari e toque no botão Compartilhar (quadrado com seta) na parte inferior da tela.",
  "pwa.iosStep2": "Role para baixo e toque em \"Adicionar à Tela de Início\".",
