  "orgTutorPolicy.title": "Regras internas para professores",
  "orgTutorPolicy.intro": "Leia as regras internas da organização antes de usar a plataforma.",
  "orgTutorPolicy.acceptBtn": "Entendi",
  "orgTutorPolicy.viewBtn": "Ver regras internas",
  "orgTutorPolicy.s1Title": "1. Disposições gerais",
  "orgTutorPolicy.s1Body": "Estas regras regem seu uso da plataforma Tutlio (a \"Plataforma\") como professor ou professor particular (o \"Professor\"). Você foi convidado a usar a Plataforma pela empresa de serviços educacionais, escola ou centro de aulas particulares que representa (a \"Organização\"). A manutenção técnica e o suporte da Plataforma são realizados pela MB Tutlio. Ao usar sua conta, você concorda com estas Regras e com a Política de Privacidade.",
  "orgTutorPolicy.s2Title": "2. Gestão da conta e agendas",
  "orgTutorPolicy.s2Intro": "A Plataforma foi desenvolvida para que você não precise gastar tempo combinando horários de aulas com os alunos.",
  "orgTutorPolicy.s2Link": "Link exclusivo: você recebe um link pessoal de agendamento de aulas (com base nas disciplinas que ensina), que os alunos usam para agendar aulas.",
  "orgTutorPolicy.s2Calendar": "Sincronização do calendário: sua disponibilidade depende diretamente da integração com o Google Agenda (sincronização de 2 vias). Você é pessoalmente responsável por garantir que os horários livres exibidos no calendário estejam corretos e atualizados. A Plataforma não permitirá que os alunos agendem horários marcados como ocupados no seu calendário.",
  "orgTutorPolicy.s2Security": "Segurança da conta: sua conta é pessoal. Você deve manter suas credenciais de acesso seguras e não compartilhá-las com terceiros.",
  "orgTutorPolicy.s3Title": "3. Cancelamento de aulas e lista de espera",
  "orgTutorPolicy.s3Intro": "A Plataforma ajuda a aproveitar ao máximo sua agenda e evitar horários vazios:",
  "orgTutorPolicy.s3Auto": "Se um aluno cancelar uma aula, a Plataforma enviará automaticamente uma notificação (SMS/e-mail) a outros alunos da sua lista de espera, oferecendo o horário liberado. Nenhuma ação adicional será necessária de sua parte.",
  "orgTutorPolicy.s3Rules": "As regras de cancelamento de aulas (antecedência necessária para cancelar e consequências) são definidas pela sua Organização.",
  "orgTutorPolicy.s4Title": "4. Finanças e pagamentos",
  "orgTutorPolicy.s4Intro": "Você não precisa se preocupar com a emissão de faturas ou a cobrança de pagamentos dos responsáveis:",
  "orgTutorPolicy.s4Advance": "Todos os pagamentos dos alunos (ou responsáveis) pelas suas aulas são cobrados antecipadamente pela Plataforma e transferidos diretamente para sua Organização.",
  "orgTutorPolicy.s4Confirmed": "Você ministra uma aula somente quando ela está confirmada no sistema (o que significa que já foi cobrada).",
  "orgTutorPolicy.s4Contact": "Para tratar de sua remuneração, calendário de repasses e outros assuntos financeiros, entre em contato diretamente com o administrador da sua Organização. A MB Tutlio não realiza transações financeiras diretas com os Professores.",
  "orgTutorPolicy.s5Title": "5. Proteção de dados dos alunos (GDPR)",
  "orgTutorPolicy.s5Intro": "Como Professor, você tem acesso aos dados pessoais dos alunos, anotações internas e materiais de aprendizagem. Você se compromete a:",
  "orgTutorPolicy.s5Use": "Usar esses dados exclusivamente para organizar e ministrar aulas.",
  "orgTutorPolicy.s5NoCopy": "Não copiar, exportar ou distribuir informações de contato de alunos ou responsáveis fora da Plataforma.",
  "orgTutorPolicy.s5Notes": "Proteger os registros internos da Organização (anotações sobre o progresso dos alunos), visíveis apenas para você e para a administração da Organização, e não para alunos ou responsáveis.",
  "orgTutorPolicy.s5Termination": "Ao encerrar seu vínculo profissional com a Organização, seu acesso a esses dados será revogado imediatamente.",
  "orgTutorPolicy.s6Title": "6. Funcionamento técnico e limitação de responsabilidade",
  "orgTutorPolicy.s6Body": "É proibido usar a Plataforma para fins ilícitos, distribuir links maliciosos nos materiais das aulas ou prejudicar o funcionamento do sistema de qualquer outra forma. A MB Tutlio garante o funcionamento e a manutenção técnica da Plataforma, mas não assume responsabilidade por interrupções causadas pela sua conexão à internet, falhas de dispositivos ou configurações incorretas do Google Agenda.",
  "orgTutorPolicy.s7Title": "7. Suporte e contatos",
  "orgTutorPolicy.s7Org": "Para dúvidas sobre horários de aulas, remuneração, atribuição de alunos ou organização do trabalho, entre em contato com o administrador da sua Organização.",
  "orgTutorPolicy.s7Tech": "Em caso de erros técnicos da Plataforma (falha na sincronização do calendário ou no recebimento de notificações), informe o administrador da sua Organização, que entrará em contato com a equipe de suporte técnico da Tutlio.",
  "register.orgPolicyConsent": "Ao usar nossa plataforma, você concorda com as",
  "register.orgPolicyLink": "políticas internas",
