  "quiz.intro.solo.eyebrow": "Feita para educadores independentes",
  "quiz.intro.solo.title": "Seu tempo vale mais na aula do que na administração",
  "quiz.intro.solo.body": "Um negócio de aulas particulares pode parecer simples por fora, mas cada aluno acrescenta agendamentos, pagamentos, anotações, lembretes e mensagens.",
  "quiz.intro.solo.visualAlt": "Professor autônomo dando aula enquanto a Tutlio conecta as etapas da gestão das aulas",
