  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Professora de química e biologia",
  "quiz.offer.testimonial.solo.copy3": "“Uma página pública e o agendamento em um único link ajudam novos alunos a decidir mais rápido, e eu não preciso mais enviar as mesmas informações a cada pessoa.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Professor de física",
  "quiz.offer.testimonial.solo.copy4": "“Consigo ver imediatamente as aulas, alterações e situações de pagamento no calendário. A administração diária ficou muito mais rápida e clara.”",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "Equipe de uma organização de aulas particulares",
  "quiz.offer.testimonial.company.copy1": "“As alterações nas aulas, os comentários dos professores e as horas trabalhadas chegavam em mensagens separadas. Agora, a equipe administrativa consegue ver o quadro completo em uma única agenda.”",
  "quiz.offer.testimonial.company.name2": "Centro independente de aulas particulares",
  "quiz.offer.testimonial.company.role2": "Proprietário · 8 professores",
  "quiz.offer.testimonial.company.copy2": "“Eu passava as noites de sexta-feira comparando o calendário com as mensagens dos professores antes de preparar a folha de pagamento. Com a Tutlio, a maior parte dessa conferência já está feita.”",
  "quiz.offer.testimonial.company.name3": "Estúdio de aulas de idiomas",
  "quiz.offer.testimonial.company.role3": "Responsável por operações · 14 professores",
  "quiz.offer.testimonial.company.copy3": "“Quando uma aula muda, a equipe vê a mesma atualização imediatamente. Temos menos mensagens de acompanhamento, e os responsáveis recebem respostas muito mais claras.”",
  "quiz.offer.testimonial.company.name4": "Centro de preparação para provas",
  "quiz.offer.testimonial.company.role4": "Coordenador financeiro · 22 professores",
  "quiz.offer.testimonial.company.copy4": "“Nossas regras de remuneração variam conforme o tipo de aula, então o fechamento do mês exigia muita conferência manual. O fluxo da Tutlio tornou esse processo muito mais tranquilo.”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "Equipe de administração escolar",
  "quiz.offer.testimonial.school.copy1": "“A melhoria mais clara é ver a situação do contrato, da assinatura e do pagamento sem precisar perguntar a várias pessoas ou conferir arquivos separados.”",
  "quiz.offer.testimonial.school.name2": "Escola comunitária independente",
  "quiz.offer.testimonial.school.role2": "Coordenador de matrículas · 86 alunos",
  "quiz.offer.testimonial.school.copy2": "“A época de matrículas significava acompanhar formulários, dados dos responsáveis e contratos assinados em pastas separadas. Agora, nossa equipe consegue acompanhar cada família em um único lugar.”",
  "quiz.offer.testimonial.school.name3": "Centro de aprendizagem extracurricular",
  "quiz.offer.testimonial.school.role3": "Administrador · 120 alunos",
  "quiz.offer.testimonial.school.copy3": "“Os parcelamentos tornaram o acompanhamento dos pagamentos muito mais tranquilo. Consigo ver o que está a vencer antes de falar com um responsável, em vez de refazer a lista à mão.”",
  "quiz.offer.testimonial.school.name4": "Escola de educação artística",
  "quiz.offer.testimonial.school.role4": "Coordenador financeiro · 9 programas",
  "quiz.offer.testimonial.school.copy4": "“A exportação para a contabilidade agora vem dos mesmos registros que usamos para contratos e pagamentos, então o fechamento do mês exige muito menos correções.”",
