  "schoolsLanding.faq.whoForQ": "Para quem é a Tutlio Schools?",
  "schoolsLanding.faq.whoForA": "Escolas de idiomas, centros de reforço, escolas de música, cursos preparatórios e qualquer organização que gerencie vários professores e alunos.",
