  "schoolsLanding.faq.pricingA": "As escolas recebem um preço sob medida conforme o número de professores e as necessidades. Fale com a gente para uma proposta personalizada.",
  "schoolsLanding.faq.trialQ": "Podemos testar antes de contratar?",
