  "nav.compare": "Comparação",
  "landing.custom.badge": "A grande diferença",
  "landing.custom.title": "Software que se adapta ao seu jeito de trabalhar - e não o contrário",
  "landing.custom.sub": "Cada escola e cada agência funciona de um jeito um pouco diferente. Quando o fluxo padrão não serve, adaptamos a Tutlio ao seu processo - normalmente em semanas, não em trimestres. Alguns exemplos que já construímos para clientes:",
  "landing.custom.ex1Title": "Contratos anuais com assinatura eletrônica",
  "landing.custom.ex1Desc": "Uma escola particular precisava que os responsáveis assinassem os contratos anuais on-line, pagassem parcelado e que cada pagamento aparecesse em uma exportação pronta para a contabilidade. Hoje todo o ciclo acontece dentro da Tutlio.",
  "landing.custom.ex2Title": "Regras de pagamento e comissão dos professores",
  "landing.custom.ex2Desc": "Uma agência paga cada professor conforme a disciplina e o tipo de aula, somando uma comissão da empresa. Modelamos as regras deles, e assim os extratos mensais dos professores e as faturas saem automaticamente.",
  "landing.custom.ex3Title": "Ofertas para os responsáveis em um clique",
  "landing.custom.ex3Desc": "Uma escola queria oferecer aulas extras por e-mail e deixar os responsáveis aceitarem com um único clique - sem conta e sem impressão. Hoje a aceitação, a cobrança e o convite para a primeira aula acontecem sozinhos.",
  "landing.custom.ex4Title": "Sua marca, no seu site",
  "landing.custom.ex4Desc": "Uma organização queria o próprio logo e as próprias cores, além de um login incorporado ao site, para que alunos e responsáveis nunca sentissem que saíram dele. Hoje a Tutlio roda sob a marca deles.",
  "landing.custom.note": "Nada disso é uma edição especial. Cada adaptação passa a fazer parte do mesmo produto que sua equipe já usa, com todas as atualizações futuras incluídas.",
  "landing.custom.cta": "Conte como você trabalha",
  "landing.custom.soloTitle": "Falta alguma coisa?",
  "landing.custom.soloNote": "Criamos recursos para clientes específicos com frequência - de uma regra de pagamento a um fluxo de trabalho inteiro. Conte o que economizaria seu tempo.",
  "compStu.debtNo": "Não",
  "stats.cancellationPartTutor": "professor: {count}",
  "compare.hub.badge": "Comparação",
  "compare.hub.title": "O Tutlio comparado a outros programas de gestão de aulas particulares",
  "compare.hub.subtitle": "Comparações honestas, ponto a ponto, com as ferramentas que professores particulares e centros de reforço escolar mais consideram. Quando um concorrente atende melhor, a gente fala.",
  "compare.hub.metaTitle": "Tutlio vs TutorBird, TutorCruncher, Teachworks, Oases | Tutlio",
  "compare.hub.metaDesc": "O Tutlio comparado a TutorBird, TutorCruncher, Teachworks e Oases Online: recursos, modelos de preço, idiomas e para quem cada ferramenta funciona melhor.",
  "compare.hub.cardCta": "Ler a comparação",
